(()=>{
 'use strict';
 if(window.DEEN_SURAH_PACK)return;
 window.DEEN_SURAH_PACK=Object.freeze({"version":1,"verification":"source-verbatim","sources":{"ar":{"provider":"Tanzil Project","edition":"Uthmani (Hafs)","license":"CC BY 3.0, verbatim copies only","url":"https://tanzil.net/docs/text_license","sha256":"adaebb377c60eba1bab6ef652959c7a0b4ccb4d0ca42145945c14ecdbeb4b761"},"tr":{"provider":"QuranEnc.com","edition":"Ali Özek ve ark. (turkish_shahin)","version":"1.0.0","license":"QuranEnc re-publication terms: unmodified, credited, version stated","url":"https://quranenc.com/en/browse/turkish_shahin","sha256":"681d48b91b93c122e383ecc7d05c80555bdd63a0487a2bb081866ea5a10dd70a"},"en":{"provider":"Marmaduke Pickthall","edition":"The Meaning of the Glorious Koran (1930)","license":"Public domain","sha256":"f93ecb2a50578c9cc4e5b89630e79fa9bcdd1d289b1a858f2aedf5aa55e8194a"}},"levels":[{"id":1,"max":8},{"id":2,"max":15},{"id":3,"max":99}],"surahs":[{"id":"qadr","number":97,"name":"Kadir","level":1,"nameAr":"القدر","ayahs":[{"n":1,"ar":"إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ","tr":"Biz onu (Kur'an'ı) Kadir gecesinde indirdik.","en":"Lo! We revealed it on the Night of Predestination"},{"n":2,"ar":"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ","tr":"Kadir gecesinin ne olduğunu sen bilir misin?","en":"Ah, what will convey unto thee what the Night of Power is"},{"n":3,"ar":"لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ","tr":"Kadir gecesi, bin aydan hayırlıdır.","en":"The Night of Power is better than a thousand months"},{"n":4,"ar":"تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ","tr":"O gecede, Rablerinin izniyle melekler ve Ruh (Cebrail), her iş için iner dururlar.","en":"The angels and the Spirit descend therein, by the permission of their Lord, with all decrees"},{"n":5,"ar":"سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ","tr":"O gece, esenlik doludur. Ta fecrin doğuşuna kadar.","en":"(The night is) Peace until the rising of the dawn"}]},{"id":"takathur","number":102,"name":"Tekâsür","level":1,"nameAr":"التكاثر","ayahs":[{"n":1,"ar":"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ","tr":"Çokluk kuruntusu sizi o derece oyaladı ki,","en":"Rivalry in worldly increase distracteth you"},{"n":2,"ar":"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ","tr":"nihayet kabirleri ziyaret ettiniz.","en":"Until ye come to the graves"},{"n":3,"ar":"كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Hayır! Yakında bileceksiniz!","en":"Nay, but ye will come to know"},{"n":4,"ar":"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","tr":"Elbette yakında bileceksiniz!","en":"Nay, but ye will come to know"},{"n":5,"ar":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ","tr":"Gerçek öyle değil ! Kesin bilgi ile bilmiş olsaydınız,","en":"Nay, would that ye knew (now) with a sure knowledge"},{"n":6,"ar":"لَتَرَوُنَّ ٱلْجَحِيمَ","tr":"(orada) mutlaka cehennem ateşini görürdünüz.","en":"For ye will behold hell-fire"},{"n":7,"ar":"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ","tr":"Sonra ahirette onu çıplak gözle göreceksiniz.","en":"Aye, ye will behold it with sure vision"},{"n":8,"ar":"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ","tr":"Nihayet o gün (dünyada yararlandığınız) nimetlerden elbette ve elbette hesaba çekileceksiniz.","en":"Then, on that day, ye will be asked concerning pleasure"}]},{"id":"humaza","number":104,"name":"Hümeze","level":2,"nameAr":"الهمزة","ayahs":[{"n":1,"ar":"وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ","tr":"Arkadan çekiştirmeyi, yüze karşı eğlenmeyi âdet edinen herkesin vay haline!","en":"Woe unto every slandering traducer"},{"n":2,"ar":"ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ","tr":"O ki, mal toplamış ve onu sayıp durmuştur.","en":"Who hath gathered wealth (of this world) and arranged it"},{"n":3,"ar":"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","tr":"(O), malının kendisini ebedi kılacağını zanneder.","en":"He thinketh that his wealth will render him immortal"},{"n":4,"ar":"كَلَّا لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ","tr":"Hayır! Andolsun ki o, Hutame'ye atılacaktır.","en":"Nay, but verily he will be flung to the Consuming One"},{"n":5,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ","tr":"Hutame'nin ne olduğunu bilir misin?","en":"Ah, what will convey unto thee what the Consuming One is"},{"n":6,"ar":"نَارُ ٱللَّهِ ٱلْمُوقَدَةُ","tr":"Allah'ın, tutuşturulmuş, ateşidir.","en":"(It is) the fire of Allah, kindled"},{"n":7,"ar":"ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ","tr":"(Yandıkça) tırmanıp kalplerin ta üstüne çıkan","en":"Which leapeth up over the hearts (of men)"},{"n":8,"ar":"إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ","tr":"ve o vaziyette o (ateş) üzerlerine kapatılmıştır.","en":"Lo! it is closed in on them"},{"n":9,"ar":"فِى عَمَدٍ مُّمَدَّدَةٍۭ","tr":"Onlar (bu ateşin içinde) uzatılmış sütunlara bağlanmışlar.","en":"In outstretched columns"}]},{"id":"duha","number":93,"name":"Duhâ","level":2,"nameAr":"الضحى","ayahs":[{"n":1,"ar":"وَٱلضُّحَىٰ","tr":"Kuşluk vaktine yemin ederim ki","en":"By the morning hours"},{"n":2,"ar":"وَٱلَّيْلِ إِذَا سَجَىٰ","tr":"ve sükuna erdiğinde geceye yemin ederim ki","en":"And by the night when it is stillest"},{"n":3,"ar":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","tr":"Rabbin seni bırakmadı ve sana darılmadı.","en":"Thy Lord hath not forsaken thee nor doth He hate thee"},{"n":4,"ar":"وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ","tr":"Gerçekten senin için ahiret dünyadan daha hayırlıdır.","en":"And verily the latter portion will be better for thee than the former"},{"n":5,"ar":"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","tr":"Pek yakında Rabbin sana verecek de hoşnut olacaksın .","en":"And verily thy Lord will give unto thee so that thou wilt be content"},{"n":6,"ar":"أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ","tr":"O, seni yetim bulup barındırmadı mı?","en":"Did He not find thee an orphan and protect (thee)"},{"n":7,"ar":"وَوَجَدَكَ ضَآلًّا فَهَدَىٰ","tr":"Şaşırmış bulup da yol göstermedi mi?","en":"Did He not find thee wandering and direct (thee)"},{"n":8,"ar":"وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ","tr":"Seni fakir bulup zengin etmedi mi?","en":"Did He not find thee destitute and enrich (thee)"},{"n":9,"ar":"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","tr":"Öyleyse yetimi sakın ezme.","en":"Therefor the orphan oppress not"},{"n":10,"ar":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","tr":"El açıp isteyeni de sakın azarlama.","en":"Therefor the beggar drive not away"},{"n":11,"ar":"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","tr":"Ve Rabbinin nimetini minnet ve şükranla an.","en":"Therefor of the bounty of thy Lord be thy discourse"}]},{"id":"adiyat","number":100,"name":"Âdiyât","level":2,"nameAr":"العاديات","ayahs":[{"n":1,"ar":"وَٱلْعَٰدِيَٰتِ ضَبْحًا","tr":"Harıl harıl koşanlara, yemin ederim ki,","en":"By the snorting courses"},{"n":2,"ar":"فَٱلْمُورِيَٰتِ قَدْحًا","tr":"(nallarıyla) çakarak kıvılcım saçanlara yemin ederim ki,","en":"Striking sparks of fire"},{"n":3,"ar":"فَٱلْمُغِيرَٰتِ صُبْحًا","tr":"(ansızın) sabah baskını yapanlara, yemin ederim ki,","en":"And scouring to the raid at dawn"},{"n":4,"ar":"فَأَثَرْنَ بِهِۦ نَقْعًا","tr":"orada tozu dumana katanlara, yemin ederim ki,","en":"Then, therewith, with their trail of dust"},{"n":5,"ar":"فَوَسَطْنَ بِهِۦ جَمْعًا","tr":"derken orada bir topluluğun ta ortasına girenlere yemin ederim ki,","en":"Cleaving, as one, the centre (of the foe)"},{"n":6,"ar":"إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌ","tr":"insan, Rabbine karşı pek nankördür.","en":"Lo! man is an ingrate unto his Lord"},{"n":7,"ar":"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ","tr":"Şüphesiz buna kendisi de şahittir","en":"And lo! he is a witness unto that"},{"n":8,"ar":"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ","tr":"ve o, mal sevgisine de aşırı derecede düşkündür.","en":"And lo! in the love of wealth he is violent"},{"n":9,"ar":"أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","tr":"(İnsan) düşünmez mi ki, kabirlerde bulunanlar diriltilip dışarı atıldığı zaman,","en":"Knoweth he not that, when the contents of the graves are poured forth"},{"n":10,"ar":"وَحُصِّلَ مَا فِى ٱلصُّدُورِ","tr":"Ve kalplerde gizlenenler ortaya konduğu zaman (hali ne olacak)!","en":"And the secrets of the breasts are made known"},{"n":11,"ar":"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ","tr":"Şüphesiz Rableri o gün onlardan tamamıyla haberdardır.","en":"On that day will their Lord be perfectly informed concerning them"}]},{"id":"qaria","number":101,"name":"Kâria","level":2,"nameAr":"القارعة","ayahs":[{"n":1,"ar":"ٱلْقَارِعَةُ","tr":"Kapı çalan!","en":"The Calamity"},{"n":2,"ar":"مَا ٱلْقَارِعَةُ","tr":"Nedir o kapı çalan?","en":"What is the Calamity"},{"n":3,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ","tr":"O kapı çalanın ne olduğunu bilir misin?","en":"Ah, what will convey unto thee what the Calamity is"},{"n":4,"ar":"يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ","tr":"İnsanların, ateşin etrafını sarmış pervaneler gibi olduğu,","en":"A day wherein mankind will be as thickly-scattered moths"},{"n":5,"ar":"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ","tr":"dağların da atılmış renkli yüne dönüştüğü gündür (o Kâria!)","en":"And the mountains will become as carded wool"},{"n":6,"ar":"فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","tr":"O gün kimin tartıları ameli ağır gelirse","en":"Then, as for him whose scales are heavy (with good works)"},{"n":7,"ar":"فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ","tr":"işte o, hoşnut edici bir yaşayış içinde olur.","en":"He will live a pleasant life"},{"n":8,"ar":"وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","tr":"Kimin tartısı da hafif gelirse ,","en":"But as for him whose scales are light"},{"n":9,"ar":"فَأُمُّهُۥ هَاوِيَةٌ","tr":"işte onun anası (yeri, yurdu) Hâviye' dir.","en":"A bereft and Hungry One will be his mother"},{"n":10,"ar":"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","tr":"Nedir o (Hâviye) bilir misin?","en":"Ah, what will convey unto thee what she is"},{"n":11,"ar":"نَارٌ حَامِيَةٌۢ","tr":"Kızgın ateş!","en":"Raging Fire"}]},{"id":"shams","number":91,"name":"Şems","level":2,"nameAr":"الشمس","ayahs":[{"n":1,"ar":"وَٱلشَّمْسِ وَضُحَىٰهَا","tr":"Güneşe ve kuşluk vaktindeki aydınlığına, yemin ederim ki,","en":"By the sun and his brightness"},{"n":2,"ar":"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","tr":"güneşi takip ettiğinde aya, yemin ederim ki,","en":"And the moon when she followeth him"},{"n":3,"ar":"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","tr":"onu açığa çıkarttığında gündüze, yemin ederim ki,","en":"And the day when it revealeth him"},{"n":4,"ar":"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","tr":"onu örttüğünde geceye, yemin ederim ki,","en":"And the night when it enshroudeth him"},{"n":5,"ar":"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","tr":"gökyüzüne ve onu bina edene, yemin ederim ki,","en":"And the heaven and Him Who built it"},{"n":6,"ar":"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","tr":"yere ve onu yapıp döşeyene, yemin ederim ki,","en":"And the earth and Him Who spread it"},{"n":7,"ar":"وَنَفْسٍ وَمَا سَوَّىٰهَا","tr":"nefse ve ona birtakım kabiliyetler verip de yemin ederim ki,","en":"And a soul and Him Who perfected it"},{"n":8,"ar":"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","tr":"iyilik ve kötülüklerini ilham edene yemin ederim ki,","en":"And inspired it (with conscience of) what is wrong for it and (what is) right for it"},{"n":9,"ar":"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","tr":"nefsini kötülüklerden arındıran kurtuluşa ermiş,","en":"He is indeed successful who causeth it to grow"},{"n":10,"ar":"وَقَدْ خَابَ مَن دَسَّىٰهَا","tr":"onu kötülüklere gömen de ziyan etmiştir.","en":"And he is indeed a failure who stunteth it"},{"n":11,"ar":"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","tr":"Semûd kavmi azgınlığı yüzünden (Allah'ın elçisini) yalanladı.","en":"(The tribe of) Thamud denied (the truth) in their rebellious pride"},{"n":12,"ar":"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","tr":"Onların en bedbahtı (deveyi kesmek için) atıldığında,","en":"When the basest of them broke forth"},{"n":13,"ar":"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا","tr":"Allah’ın Rasûlü onlara: «Allah’ın devesine ve onun su hakkına dokunmayın!» dedi.","en":"And the messenger of Allah said: It is the she-camel of Allah, so let her drink"},{"n":14,"ar":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","tr":"Ama onlar, onu yalanladılar ve deveyi kestiler. Bunun üzerine Rableri günahları sebebiyle onlara büyük bir felâket gönderdi de hepsini helâk etti.","en":"But they denied him, and they hamstrung her, so Allah doomed them for their sin and rased (their dwellings)"},{"n":15,"ar":"وَلَا يَخَافُ عُقْبَٰهَا","tr":"(Allah, bu şekilde azap etmenin) âkıbetinden korkacak değil ya!","en":"He dreadeth not the sequel (of events)"}]},{"id":"tariq","number":86,"name":"Târık","level":3,"nameAr":"الطارق","ayahs":[{"n":1,"ar":"وَٱلسَّمَآءِ وَٱلطَّارِقِ","tr":"Gökyüzüne ve târıka (sabah yıldızına ) yemin ederim.","en":"By the heaven and the Morning Star"},{"n":2,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","tr":"Tarıkın ne olduğunu nereden bileceksin?","en":"Ah, what will tell thee what the Morning Star is"},{"n":3,"ar":"ٱلنَّجْمُ ٱلثَّاقِبُ","tr":"(O, karanlığı) delen yıldızdır.","en":"The piercing Star"},{"n":4,"ar":"إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ","tr":"Hiç kimse yoktur ki üzerinde bir koruyucu, bir denetleyici bulunmasın.","en":"No human soul but hath a guardian over it"},{"n":5,"ar":"فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ","tr":"İnsan neden yaratıldığına bir baksın!","en":"So let man consider from what he is created"},{"n":6,"ar":"خُلِقَ مِن مَّآءٍ دَافِقٍ","tr":"Atılan bir sudan yaratıldı.","en":"He is created from a gushing fluid"},{"n":7,"ar":"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","tr":"(O su) sırt ile göğüs kafesi arasından çıkar.","en":"That issued from between the loins and ribs"},{"n":8,"ar":"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ","tr":"İşte Allah (başlangıçta bu şekilde yarattığı) insanı tekrar yaratmaya da kadirdir.","en":"Lo! He verily is Able to return him (unto life)"},{"n":9,"ar":"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","tr":"Gizlenenlerin ortaya döküldüğü günde","en":"On the day when hidden thoughts shall be searched out"},{"n":10,"ar":"فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ","tr":"insan için ne bir güç ne de bir yardımcı vardır.","en":"Then will he have no might nor any helper"},{"n":11,"ar":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","tr":"Dönüş sahibi olan (yağmur yağdıran) göğe,","en":"By the heaven which giveth the returning rain"},{"n":12,"ar":"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","tr":"(nebat ile) yarılan yere yemin ederim ki","en":"And the earth which splitteth (with the growth of trees and plants)"},{"n":13,"ar":"إِنَّهُۥ لَقَوْلٌ فَصْلٌ","tr":"Kur’an, (hak ile bâtılı) ayıran bir sözdür.","en":"Lo! this (Qur'an) is a conclusive word"},{"n":14,"ar":"وَمَا هُوَ بِٱلْهَزْلِ","tr":"O, asla bir şaka değildir.","en":"It is no pleasantry"},{"n":15,"ar":"إِنَّهُمْ يَكِيدُونَ كَيْدًا","tr":"Onlar bir tuzak kurarlar,","en":"Lo! they plot a plot (against thee, O Muhammad)"},{"n":16,"ar":"وَأَكِيدُ كَيْدًا","tr":"ben de bir tuzak kurarım.","en":"And I plot a plot (against them)"},{"n":17,"ar":"فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","tr":"Kâfirlere mühlet ver, onları biraz kendi hallerine bırak (pek yakında desteğimiz sana gelecek).","en":"So give a respite to the disbelievers. Deal thou gently with them for a while"}]},{"id":"ala","number":87,"name":"A‘lâ","level":3,"nameAr":"الأعلى","ayahs":[{"n":1,"ar":"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","tr":"Yüce Rabbinin adını tesbih (ve takdis) et.","en":"Praise the name of thy Lord the Most High"},{"n":2,"ar":"ٱلَّذِى خَلَقَ فَسَوَّىٰ","tr":"Yaratıp düzene koyan,","en":"Who createth, then disposeth"},{"n":3,"ar":"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","tr":"takdir edip yol gösteren,","en":"Who measureth, then guideth"},{"n":4,"ar":"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","tr":"(topraktan) yeşil otu çıkarıp","en":"Who bringeth forth the pasturage"},{"n":5,"ar":"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","tr":"sonra da onu kapkara bir sel artığına çeviren.","en":"Then turneth it to russet stubble"},{"n":6,"ar":"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","tr":"Sana (Kur'an'ı) okutacağız; sen hiç unutmayacaksın.","en":"We shall make thee read (O Muhammad) so that thou shalt not forget"},{"n":7,"ar":"إِلَّا مَا شَآءَ ٱللَّهُ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","tr":"Artık Allah'ın dilediği hariç, şüphesiz Allah, açığı ve gizleneni bilir.","en":"Save that which Allah willeth. Lo! He knoweth the disclosed and that which still is hidden"},{"n":8,"ar":"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","tr":"Seni en kolaya muvaffak kılacağız.","en":"And We shall ease thy way unto the state of ease"},{"n":9,"ar":"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","tr":"O halde eğer öğüt fayda verirse öğüt ver.","en":"Therefor remind (men), for of use is the reminder"},{"n":10,"ar":"سَيَذَّكَّرُ مَن يَخْشَىٰ","tr":"(Allah'tan) korkan öğütten yararlanacak.","en":"He will heed who feareth"},{"n":11,"ar":"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","tr":"Kötü kimse ise öğütten kaçınır.","en":"But the most hapless will flout it"},{"n":12,"ar":"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","tr":"En büyük ateşe girecek olan","en":"He who will be flung to the great Fire"},{"n":13,"ar":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","tr":"sonra o, ateşte ne ölür ne de yaşar.","en":"Wherein he will neither die nor live"},{"n":14,"ar":"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","tr":"Temizlenen, kimse kuşkusuz kurtuluşa ermiştir.","en":"He is successful who groweth"},{"n":15,"ar":"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","tr":"Rabbinin adını anıp O'na kulluk eden.","en":"And remembereth the name of his Lord, so prayeth"},{"n":16,"ar":"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","tr":"Fakat siz (ey insanlar!) dünya hayatını tercih ediyorsunuz.","en":"But ye prefer the life of the world"},{"n":17,"ar":"وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ","tr":"Ahiret daha hayırlı ve daha devamlı olduğu halde.","en":"Although the Hereafter is better and more lasting"},{"n":18,"ar":"إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","tr":"Şüphesiz bu (anlatılanlar), önceki kitaplarda,","en":"Lo! This is in the former scrolls"},{"n":19,"ar":"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","tr":"İbrahim ve Musa'nın kitaplarında da vardır.","en":"The Books of Abraham and Moses"}]},{"id":"alaq","number":96,"name":"Alak","level":3,"nameAr":"العلق","ayahs":[{"n":1,"ar":"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","tr":"Yaratan Rabbinin adıyla oku!","en":"Read: In the name of thy Lord Who createth"},{"n":2,"ar":"خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ","tr":"O, insanı alâk (rahim cidarına asılı hücre kümesi) tan yarattı.","en":"Createth man from a clot"},{"n":3,"ar":"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","tr":"Oku! En büyük kerem sahibidir Rabbin.","en":"Read: And thy Lord is the Most Bounteous"},{"n":4,"ar":"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","tr":"Kalemle (yazmayı) öğreten Rabbin,","en":"Who teacheth by the pen"},{"n":5,"ar":"عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ","tr":"İnsana bilmediklerini belleten,","en":"Teacheth man that which he knew not"},{"n":6,"ar":"كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ","tr":"Gerçek şu ki, insan azar.","en":"Nay, but verily man is rebellious"},{"n":7,"ar":"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","tr":"Kendini kendine yeterli görerek.","en":"That he thinketh himself independent"},{"n":8,"ar":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","tr":"Kuşkusuz dönüş Rabbinedir.","en":"Lo! unto thy Lord is the return"},{"n":9,"ar":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","tr":"Men edeni gördün mü?","en":"Hast thou seen him who dissuadeth"},{"n":10,"ar":"عَبْدًا إِذَا صَلَّىٰٓ","tr":"Namaz kılarken bir kulu (Peygamber'i namazdan)","en":"A slave when he prayeth"},{"n":11,"ar":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","tr":"Ne dersin, o (Peygamber) doğru yolda ise","en":"Hast thou seen if he relieth on the guidance (of Allah)"},{"n":12,"ar":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","tr":"yahut takvâyı emrediyorsa!","en":"Or enjoineth piety"},{"n":13,"ar":"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","tr":"Ne dersin o (men eden, Peygamber'i) yalanlıyor ve doğru yoldan yüz çeviriyorsa!","en":"Hast thou seen if he denieth (Allah's guidance) and is froward"},{"n":14,"ar":"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","tr":"(Bu adam) Allah’ın, (yaptıklarını) gördüğünü bilmez mi!","en":"Is he then unaware that Allah seeth"},{"n":15,"ar":"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","tr":"Hayır, hayır! Eğer vazgeçmezse, derhal onu alnından (perçeminden),","en":"Nay, but if he cease not We will seize him by the forelock"},{"n":16,"ar":"نَاصِيَةٍ كَٰذِبَةٍ خَاطِئَةٍ","tr":"o yalancı, günahkâr alından (perçemden) yakalarız (cehenneme atarız).","en":"The lying, sinful forelock"},{"n":17,"ar":"فَلْيَدْعُ نَادِيَهُۥ","tr":"O, hemen gidip meclisini (kendi taraftarlarını) çağırsın.","en":"Then let him call upon his henchmen"},{"n":18,"ar":"سَنَدْعُ ٱلزَّبَانِيَةَ","tr":"Biz de zebanileri çağıracağız","en":"We will call the guards of hell"},{"n":19,"ar":"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب","tr":"Hayır! Ona uyma! Allah’a secde et ve (yalnızca O’na) yaklaş!","en":"Nay, Obey not thou him. But prostrate thyself, and draw near (unto Allah)"}]},{"id":"balad","number":90,"name":"Beled","level":3,"nameAr":"البلد","ayahs":[{"n":1,"ar":"لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ","tr":"Bu beldeye yemin ederim ki,","en":"Nay, I swear by this city"},{"n":2,"ar":"وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ","tr":"Sen bu beldedesin, yemin ederim ki","en":"And thou art an indweller of this city"},{"n":3,"ar":"وَوَالِدٍ وَمَا وَلَدَ","tr":"babaya ve ondan meydana gelen çocuğa yemin ederim ki,","en":"And the begetter and that which he begat"},{"n":4,"ar":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ","tr":"biz, insanı (yüzyüze geleceği nice) zorluklar içinde yarattık.","en":"We verily have created man in an atmosphere"},{"n":5,"ar":"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ","tr":"İnsan, hiç kimsenin kendisine güç yetiremeyeceğini mi sanıyor?","en":"Thinketh he that none hath power over him"},{"n":6,"ar":"يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا","tr":"«Pek çok mal harcadım» diyor.","en":"And he saith: I have destroyed vast wealth"},{"n":7,"ar":"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","tr":"Kimse onu görmedi mi sanıyor?","en":"Thinketh he that none beholdeth him"},{"n":8,"ar":"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","tr":"Biz ona iki göz, vermedik mi?","en":"Did We not assign unto him two eyes"},{"n":9,"ar":"وَلِسَانًا وَشَفَتَيْنِ","tr":"Bir dil ve iki dudak vermedik mi?","en":"And a tongue and two lips"},{"n":10,"ar":"وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ","tr":"Ona iki yolu (doğru ve eğriyi) göstermedik mi?","en":"And guide him to the parting of the mountain ways"},{"n":11,"ar":"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","tr":"Fakat o, sarp yokuşu aşamadı.","en":"But he hath not attempted the Ascent"},{"n":12,"ar":"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","tr":"O sarp yokuş nedir bilir misin?","en":"Ah, what will convey unto thee what the Ascent is"},{"n":13,"ar":"فَكُّ رَقَبَةٍ","tr":"Köle âzat etmek","en":"(It is) to free a slave"},{"n":14,"ar":"أَوْ إِطْعَٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ","tr":"veya açlık gününde doyurmaktır.","en":"And to feed in the day of hunger"},{"n":15,"ar":"يَتِيمًا ذَا مَقْرَبَةٍ","tr":"Yakını olan bir yetimi","en":"An orphan near of kin"},{"n":16,"ar":"أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ","tr":"veya açaçık bir yoksulu.","en":"Or some poor wretch in misery"},{"n":17,"ar":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","tr":"Sonra iman edenlerden, birbirlerine sabrı tavsiye edenlerden ve birbirlerine acımayı öğütleyenlerden olmaktır.","en":"And to be of those who believe and exhort one another to perseverance and exhort one another to pity"},{"n":18,"ar":"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ","tr":"İşte bunlar sağdakilerdir.","en":"Their place will be on the right hand"},{"n":19,"ar":"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ","tr":"Âyetlerimizi inkâr edenler ise işte onlar soldakilerdir.","en":"But those who disbelieve Our revelations, their place will be on the left hand"},{"n":20,"ar":"عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ","tr":"Cezaları, kapıları üzerlerine sımsıkı, kapatılmış bir ateştir.","en":"Fire will be an awning over them"}]},{"id":"layl","number":92,"name":"Leyl","level":3,"nameAr":"الليل","ayahs":[{"n":1,"ar":"وَٱلَّيْلِ إِذَا يَغْشَىٰ","tr":"(Karanlığı ile etrafı) bürüyüp örttüğü zaman geceye, yemin ederim ki,","en":"By the night enshrouding"},{"n":2,"ar":"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","tr":"açılıp ağardığı vakit gündüze, yemin ederim ki,","en":"And the day resplendent"},{"n":3,"ar":"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","tr":"erkeği ve dişiyi yaratana yemin ederim ki,","en":"And Him Who hath created male and female"},{"n":4,"ar":"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","tr":"işleriniz başka başkadır.","en":"Lo! your effort is dispersed (toward divers ends)"},{"n":5,"ar":"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","tr":"Artık kim verir ve sakınırsa,","en":"As for him who giveth and is dutiful (toward Allah)"},{"n":6,"ar":"وَصَدَّقَ بِٱلْحُسْنَىٰ","tr":"en güzeli de tasdik ederse,","en":"And believeth in goodness"},{"n":7,"ar":"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","tr":"biz de onu en kolaya hazırlarız (onda başarılı kılarız).","en":"Surely We will ease his way unto the state of ease"},{"n":8,"ar":"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","tr":"Kim cimrilik eder, kendini müstağni sayar,","en":"But as for him who hoardeth and deemeth himself independent"},{"n":9,"ar":"وَكَذَّبَ بِٱلْحُسْنَىٰ","tr":"en güzeli de yalanlarsa,","en":"And disbelieveth in goodness"},{"n":10,"ar":"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","tr":"biz de onu en zora hazırlarız.","en":"Surely We will ease his way unto adversity"},{"n":11,"ar":"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","tr":"Düştüğü zaman da malı kendisine hiç fayda vermez.","en":"His riches will not save him when he perisheth"},{"n":12,"ar":"إِنَّ عَلَيْنَا لَلْهُدَىٰ","tr":"Doğru yolu göstermek bize aittir.","en":"Lo! Ours it is (to give) the guidance"},{"n":13,"ar":"وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ","tr":"Şüphesiz ahiret de dünya da bizimdir.","en":"And lo! unto Us belong the latter portion and the former"},{"n":14,"ar":"فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ","tr":"(Ey insanlar!) Alev alev yanan bir ateşle sizi uyardım.","en":"Therefor have I warned you of the flaming Fire"},{"n":15,"ar":"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","tr":"O ateşe, kötüler girer.","en":"Which only the most wretched must endure"},{"n":16,"ar":"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","tr":"Ancak yalanlayıp yüz çeviren.","en":"He who denieth and turneth away"},{"n":17,"ar":"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","tr":"İyiler ondan (ateşten) uzak tutulur.","en":"Far removed from it will be the righteous"},{"n":18,"ar":"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","tr":"Temizlenmek üzere malını hayra veren","en":"Who giveth his wealth that he may grow (in goodness)"},{"n":19,"ar":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ","tr":"onun nezdinde hiç bir kimseye ait şükranla karşılanacak,","en":"And none hath with him any favour for reward"},{"n":20,"ar":"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","tr":"Yüce Rabbinin rızasını istemekten başka bir nimet yoktur.","en":"Except as seeking (to fulfil) the purpose of his Lord Most High"},{"n":21,"ar":"وَلَسَوْفَ يَرْضَىٰ","tr":"Ve o (buna kavuşarak) hoşnut olacaktır.","en":"He verily will be content"}]}]});
})();
